import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"火风鼎","description":"周易折中 - 火风鼎","frontmatter":{"title":"火风鼎","description":"周易折中 - 火风鼎"},"headers":[],"relativePath":"zh/classics/zhezhong/056.md","filePath":"zh/classics/zhezhong/056.md"}'),h={name:"zh/classics/zhezhong/056.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="火风鼎" tabindex="-1">火风鼎 <a class="header-anchor" href="#火风鼎" aria-label="Permalink to “火风鼎”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈鼎序卦〉：“革物者其若鼎，故受之以鼎。鼎之为用，所以革物也。变腥而为熟，易坚而为柔，水火不可同处也，能使相合为用而不相害，是能革物也。鼎所以次革也。为卦上离下巽，所以为鼎，则取其象焉，取其义焉。取其象者有二：以全体言之，则下植为足，中实为腹，受物在中之象；对峙于上者耳也，横互乎上者铉也，鼎之象也。以上下二体言之，则中虗在上下，有足以承之，亦鼎之象也。取其义，则木从火也。巽入也，顺从之义，以木从火为然之象。火之用惟燔与烹，燔不假器，故取烹象而为鼎。以木巽火，烹饪之象也。制器取其象也，乃象器以为卦乎？曰：制器取于象也。象存乎卦，而卦不必先器。圣人制器不待见卦而后知象，以众人之不能知象也，故设卦以示之。卦、器之先后不害于义也。或疑鼎非自然之象，乃人为也。曰：固人为也，然烹饪可以成物，形制如是则可用，此非人为自然也。在井亦然，器虽在卦先，而所取者乃卦之象，卦复用器以为义也。”</p><p>鼎：元吉亨</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>鼎，烹饪之器。为卦，下阴为足，二三四阳为腹，五阴为耳，上阳为铉，有鼎之象。又以巽木入离火而致烹饪，鼎之用也。故其卦为鼎。下巽，巽也；上离为目，而五为耳，有内巽顺而外聪明之象。卦自巽来，阴进居五而下应九二之阳，故其占曰“元亨吉”。衍文也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>以卦才言也。如卦之才可以致元亨也，止当云“元亨”，文羡“吉”字。卦才可以致元亨，未便有“元吉”也。《彖》复止云“元亨”，其羡明矣。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>易氏祓曰 ：易之诸卦，皆言象取诸物以名卦者，鼎与井而已。井以木（巽）水，鼎以木（巽）火。二卦以养人为义，故皆以实象明之。</p></li><li><p>胡氏一桂曰 ：自“元亨”外无馀辞，唯大有与鼎。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>上经颐卦言养道，曰“圣人养贤以及万民”。然则王者之所当养，此两端而已。下经井言养，鼎亦言养。然井在邑里之间，往来行汲，养民之象也；鼎在朝庙之中，燕飨则用之，养贤之象也。养民者存乎政，行政者存乎人，是其得失未可知也。故井之《彖》犹多戒辞。至于能养贤，则与之食天禄，治天职，而所以养民者在是矣。故其辞直曰“元亨”，与大有同。</p><p>象曰：木上有火，鼎；君子以正位凝命</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>鼎，重器也，故有正位凝命之意。凝，犹至道不凝之凝，传所谓“协于上下以承天休者也”。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>木上有火，以木巽火也，烹饪之象，故为鼎。君子观鼎之象，以正位凝命。鼎者，法象之器，其形端正，其体安重。取其端正之象，则以正其位，谓正其所居之位。君子所处必正，其小至于席不正不坐，毋跛毋倚。取其安重之象，则凝其命令，安重其命令也。凝聚止之义，谓安重也。今世俗有凝然之语，以命令而言耳。凡动为皆当安重也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>房氏乔曰 ：鼎者，神器，至大至重，正位凝命，法其重大不可迁移也。</p></li><li><p>李氏元量曰 ：木上有火，非鼎也，鼎之用也；犹之木上有水，非井也，井之功也。</p></li><li><p>郑氏汝谐曰 ：革以改命，鼎以定命。知革而不知鼎，则天下之乱滋矣。</p></li><li><p>项氏安世曰 ：存神息气，人所以凝寿命；中心无为，以守至正，君所以凝天命。</p></li><li><p>王氏申子曰 ：鼎形端而正，体镇而重。君子取其端正之象以正其所居之位，使之愈久而愈安；取其镇重之象以凝其所受之命，使之愈久而愈固。</p></li><li><p>胡氏炳文曰 ：鼎之器正，然后可凝其所受之实；君之位正，然后可凝其所受之命。</p></li></ul><p>彖曰：鼎，象也。以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体二象释卦名义。因极其大而言之，享帝贵诚，用犊而已；养贤则饔飧牢礼，当极其盛，故曰大亨。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>卦之为鼎，取鼎之象也。鼎之为器，法卦之象也。有象而后有器，卦复用器而为义也。鼎大器也，重宝也，故其制作形模法象尤严。鼎之名正也，古人训方，方实正也。以形言，则耳对植于上，足分峙于下，周圆内外，髙卑厚薄，莫不有法，而至正。至正然后成安重之象，故鼎者法象之器。卦之为鼎，以其象也。以木巽火，以二体言鼎之用也。以木从火，所以亨饪也。鼎之为器，生人所赖至切者也。极其用之大，则圣人亨以享上帝，大亨以养圣贤。圣人古之圣王，大言其广。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>蔡氏渊曰 ：祭之大者，无出于上帝；宾客之重者，无过于圣贤。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>释名之后继以“享帝养贤”两句，指明卦义之所主也。与“井养而不穷也”对观之，便明。盖彼主养民，此主享帝养贤，而享帝之实，尤在于养贤也。</p><p>巽而耳目聪明，柔进而上行，得中而应乎刚，是以元亨</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦象、卦变、卦体释卦辞。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>上既言鼎之用矣，复以卦才言。人能如卦之才，可以致元亨也。下体巽为巽顺于理，离明而中虚，于上为耳目聪明之象。凡离在上者，皆云柔进而上行。柔在下之物，乃居尊位，进而上行也。以明居尊而得中道，应乎刚，能用刚阳之道也。五居中而又以柔而应刚，为得中道，其才如是，所以能元亨也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>单氏沨曰 ：巽以养下，则达聪而明目者也。柔进而上行，则不为骄亢者也。得中而应刚，则能养圣贤者也。</p></li><li><p>刘氏曰 ：得中而应乎刚者，以柔居中下，应九二之刚，乃能用贤也。柔得尊位，卑巽以下贤，是以致元亨。</p></li><li><p>张氏清子曰 ：上体离也，离为目而兼耳。言之者，盖以六五为鼎耳而取也。</p></li></ul><p>/books/106/50/1.html</p><p>初六 鼎颠趾，利出否，得妾以其子，无咎</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>居鼎之下，鼎趾之象也。上应九四，则颠矣。然当卦初，鼎未有实，而旧有否恶之积焉。因其颠而出之，则为利矣。得妾而因得其子，亦由是也。此爻之象如此，而其占无咎，盖因败以为功，因贱以致贵也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>六在鼎下，趾之象也。上应于四，趾而向上颠之象也。鼎覆则趾颠，趾颠则覆其实矣，非顺道也。然有当颠之时，谓倾出败恶以致洁取新，则可也。故颠趾利在于出否，否恶也。四近君大臣之位，初在下之人而相应，乃上求于下，下从其上也。上能用下之善，下能辅上之为，可以成事功，乃善道。如鼎之颠趾，有当颠之时，未为悖理也。得妾以其子无咎，六阴而卑，故为妾。得妾谓得其人也，若得良妾，则能辅助其主，使无过咎也。子，主也，以其子致其主于无咎也。六阴居下而卑巽，从阳，妾之象也。以六上应四为颠趾，而获此义。初六本无才徳可取，故云得妾，言得其人则如是也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>熊氏良辅曰：鼎颠趾，鼎之未用而倾仆也。未用而倾仆，则污秽不能留，反以颠为利也。若九四之折足，则覆败而凶矣。得妾以其子，又就颠趾出否上取义。得妾者，颠趾也；以其子者，出否也。疑于有咎，故曰无咎。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>易例中，初六应九四无亨言之义，盖以初六乃材徳之卑，应四有援上之嫌，故于义无可取者。其动于应而凶咎者，则有之矣。如鸣豫、咸拇之类是也。惟晋有上进之义，萃有萃上之义，鼎有得养之义，此三者则初六九四之应容有取焉。然晋初则晋如摧如，萃初则乃乱乃萃，盖主于在下者之求进、求萃而言，则居卑处初未能自达者宜也。惟鼎之义主于上之养下，上之养下也，大贤固养之矣，及其使人也，器之薄、材微、品所不遗焉。当此之时，虽其就上也如颠趾，而因得去污秽以自濯于洁清；虽其媒鬻也如妾，而因得广嗣续以荐身于嫔御。盛世所以无弃才，而人入于士君子之路者，此也。故观易者，知时义之为要。</p><p>象曰：鼎顚趾，未悖也；利出否，以从贵也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>鼎而顚趾，悖道也；而因可出否以从贵，则未为悖也。从贵，谓应四，亦为取新之意。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>鼎覆而趾顚，悖道也。然非必为悖者，盖有倾出否恶之时也，去故而纳新，㵼恶而受美，从贵之义也。应于四上，从于贵者也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>陆氏希声曰 ：趾当承鼎顚而覆之，悖也。于是出其恶故，虽覆未悖，犹妾至贱不当贵，以其子故得贵焉。春秋之义，母以子贵是也。</p></li><li><p>郑氏汝谐曰 ：初居下，乃鼎之趾。必顚趾者，乃出否也，犹之妾也。其可从上以子，子贵则母贵也。凡取新之义，必舍恶而取善，舍贱而取贵，期合于义。初之应乎四，顚趾也，从贵也。柔而应于上，必有此义乃可。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>传于得妾之辞不释，但以从贵之意包之。圣言之简而尽如此。</p><p>九二：鼎有实，我仇有疾，不我能即，吉</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>以刚居中，鼎有实之象也。我仇谓初，阴阳相求而非正则相陷于恶而为仇矣。二能以刚中自守，则初虽近，不能以就之矣。是以其象如此，而其占为如是则吉也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二以刚实居中，鼎中有实之象。鼎之有实，上出则为用。二阳刚有济用之才，与五相应，上从六五之君，则得正而其道可亨。然与初密比，阴从阳者也。九二居中而应中，不至失正。已虽自守，彼必相求，故戒能逺之使不来即我，则吉也。仇，对也，阴阳相对之物，谓初也。相从则非正而害义，是有疾也。二当以正自守，使之不能来就已。人能自守以正，则不正不能就之矣，所以吉也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：鼎诸爻与井相似，井以阳刚为泉，鼎以阳刚为实。井二无应，故其功终不上行；鼎二有应，而能以刚中自守，故吉。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>此“疾”字是妒害之义，所谓入朝见疾是也。夫相妒害，则相远而不相即矣。然小人之害人也，必托为亲爱以伺其隙，故必不恶而严，使之“不我能即”，而后无隙之可乘也。此只据九二刚中能自守而取此象，不必定指一爻为“我仇”也。</p><p>象曰：鼎有实，愼所之也；我仇有疾，终无尤也</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>有实而不谨其所往，则为仇所即而陷于恶矣。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>鼎之有实，乃人之有才业也。当愼所趋向，不愼所往，则亦陷于非义。二能不昵于初，而上从六五之正应，乃是愼所之也。我仇有疾，举上文也。我仇，对已者，谓初也。初比已而非正，是有疾也。既自守以正，则彼不能即我，所以终无过尤也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>张子曰 ：以阳居中，故有实。实而与物竞，则所丧多矣，故所之不可不愼也。</li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>尤者，已之过尤也，人之怨尤。能愼其所行，则虽我仇有疾害之心，无过尤之可指，而怨尤之念亦消矣。</p><p>九三：鼎耳革，其行塞，雉膏不食，方雨，亏悔终吉</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>以阳居鼎腹之中，本有美实者也。然以过刚失中，越五应上，又居下之极为变革之时，故为鼎耳方革而不可举移。虽承上爻文明之腴，有雉膏之美，而不得以为人之食。然以阳居阳，为得其正。苟能自守，则阴阳将和而失其悔矣。占者如是，则初虽不利，而终得吉也。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>鼎耳，六五也，为鼎之主。三以阳居巽之上，刚而能巽，其才足以济务。然与五非应而不同，五中而非正，三正而非中，不同也。未得于君者，不得于君则其道何由而行？革，变革为异也。三与五异而不合也，其行塞不能亨也。不合于君，则不得其任，无以施其用。膏，甘美之物，象禄位。雉指五也，有文明之德，故谓之雉。三有才用而不得六五之禄位，是不得雉膏食之也。君子蕴其德久而必彰，守其道，其终必亨。五有聪明之象，而三终上进之物，阴阳交畅，则雨方雨且将雨也。言五与三方将和合，亏悔终吉，谓不足之悔终当获吉也。三怀才而不偶，故有不足之悔。然其有阳刚之德，上聪明而下巽正，终必相得，故吉也。三虽不中，以巽体故无过刚之失，若过刚则岂能终吉。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>易氏祓曰 ：九三鼎腹有实者也。耳谓六五，正所以运其腹中所容者。惟上无应，塞而不行，实在其中，美如雉膏，谁得而享之？然君子处心，要使美实备于我，而不计行之通塞。及其终也，阴阳相济，有至和将雨之兆。此所以亏其始之悔，而终必获吉也。</p></li><li><p>胡氏炳文曰 ：井、鼎九三皆居下而未为时用。井三如清洁之泉而不见食，鼎三如鼎中有雉膏而不得以为人食。然君子能为可食，不能使人必食。六五鼎耳，三与五不相遇，如鼎耳方变革而不可举移，故其行不通。然五文明之主，三上承文明之腴，以刚正自守，五终当求之。方且如阴阳和而为雨，始虽有不遇之悔，终当有相遇之吉。井三所谓“王明并受其福”者，亦犹是也。</p></li></ul><p>象曰：鼎耳革，失其义也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>始与鼎耳革异者，失其相求之义也。与五非应，失求合之道也。不中，非同志之象也。是以其行塞而不通，然上明而下才，终必和合，故方雨而吉也。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>象传凡言义者，谓卦义也。此失其义，非谓已之所行失义，盖谓爻象无相应之义尔。</p><p>九四：鼎折足，覆公𫗧，其形渥，凶</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>晁氏曰：“形渥”诸本作“刑剭”，谓重刑也，今从之。九四居上，任重者也，而下应初六之阴，则不胜其任矣。故其象如此，而其占凶也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四大臣之位，任天下之事者也。天下之事，岂一人所能独任，必当求天下之贤智与之协力。得其人，则天下之治可不劳而致；用非其人，则败国家之事，贻天下之患。四下应于初，初阴柔小人不可用者也，而四用之，其不胜任而败事，犹鼎之折足也。鼎折足则倾覆，公上之𫗧（注：此处应为鼎中实物），鼎实也。居大臣之位，当天下之任，而所用非人，至于覆败，乃不胜其任，可羞愧之甚也。其形渥，谓赧汗也，其凶可知。《系辞》曰：“德薄而位尊，知小而谋大，力少而任重，鲜不及矣。”言不胜其任也。蔽于所私，德薄知小也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：渥，沾濡之貌也。既覆公𫗧，体为沾濡，知小谋大，不堪其任，受其至辱，灾及其身，故曰“其形渥凶”也。</p></li><li><p>胡氏瑗曰 ：夫鼎之实，必有齐量，不可以盈溢。若遇其盈溢，则有覆𫗧之凶。君子之人，虽有才德，亦有分量。若职事过其才分，则有堕官之谤矣。</p></li><li><p>苏氏轼曰 ：鼎之量极于四，其上则耳矣。受实必有馀量以为溢地也，溢则覆矣。</p></li><li><p>朱氏震曰 ：其形渥，羞赧之象，泽流被面，沾濡其体也。</p></li><li><p>易氏祓曰 ：四亦鼎腹有实，在二阳之上，已过于溢，而又以阳刚之才下应于初。初趾已颠，故有折足之象。覆公𫗧，四近君为公之象。</p></li><li><p>胡氏炳文曰 ：初未有鼎实，故因颠趾而出否；四已有鼎实，故折足而覆𫗧。案：四之得凶，诸家之说备矣。盖三阳为实，而四适当其盈也。盈则有倾覆之象矣，又应初为无辅，故有折足覆𫗧之象。凡易例九四应初六，皆有损而无助，《大过》之“不桡乎下”，《解》之“解而拇”，皆是也。其形渥，从王氏说为是。《诗》曰：“渥赭”、“曰渥丹”，皆以颜貌言之，愧生于中，则颜发赤也。</p></li></ul><p>象曰：覆公𫗧，信如何也</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>言失信也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>大臣当天下之任，必能成天下之治安，则不误君上之所倚，下民之所望，与已致身任道之志，不失所期，乃所谓信也。不然，则失其职，误上之委任，得为信乎？故曰“信如何也”。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏简曰 ：居大臣之位，是许国以大臣之事业也。而实则不称，折足覆𫗧，失许国之信矣。</li></ul><p>六五：鼎黄耳金铉，利贞</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>五于象为耳，而有中德，故云黄耳。金，坚刚之物，铉贯耳以举鼎者也。五虚中以应九二之坚刚，故其象如此。而其占，则利在贞固而已。或曰金铉以上九而言，更详之。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>五在鼎上，耳之象也。鼎之举措在耳，为鼎之主也。五有中德，故云黄耳。铉加耳者也，二应于五，来从于耳者，铉也。二有刚中之德，阳体刚中色黄，故为金铉。五文明得中而应刚二，刚中巽体而上应，才无不足也。相应至善矣，所利在贞固而已。六五居中应中，不至于失正，而质本阴柔，故戒以贞固于中也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏宗传曰 ：在鼎之上，受铉以举鼎者，耳也，六五之象也。在鼎之外，贯耳以举鼎者，铉也，上九之象也。</p></li><li><p>王氏申子曰 ：黄中色谓五之中也，金刚德谓上之阳也。主一鼎者在乎耳，耳不虚中，则鼎虽有铉而无所措；耳而无铉，则鼎虽有实而无所施。故鼎之六五虚中以纳上九阳刚之助，而后一鼎之实得以利及天下。犹鼎黄耳得金铉也。曰“利贞”，亦以阴居阳而有此戒。</p></li><li><p>胡氏一桂曰 ：程传及诸家多以六五下应九二为金铉，本义从之。然犹举“或曰”之说，谓金铉以上九言。窃谓铉所以举鼎者也，必在耳上方可贯耳。九二在下，势不可用。或说为优，然上九又自谓玉铉者，金象以九爻取，玉象以爻位刚柔相济取。</p></li></ul><p>象曰：鼎黄耳中，以为实也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>六五以得中为善，是以中为实德也。五之所以聪明应刚，为鼎之主，得鼎之道，皆由得中也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>陆氏绩曰 ：得中承阳，故曰“中以为实”。</p></li><li><p>郭氏雍曰 ：“中以为实”者，六五阴虚，以黄中之德为实也，犹坤之六五“美在其中”之道也。</p></li></ul><p>上九：鼎玉铉，大吉，无不利</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>上于象为铉，而以阳居阴，刚而能温，故有玉铉之象。而其占为大吉，无不利。盖有是德，则如其占也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>井与鼎，以上出为用处，终鼎功之成也。在上为铉之象，刚而温者，玉也。九虽刚阳而居阴，履柔不极刚而能温者也。居成功之道，唯善处而已。刚柔适宜，动静不过，则为大吉，无所不利矣。在上为铉，虽居无位之地，实当用也，与它卦异矣。井亦然。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>易氏祓曰 ：鼎与井，其用在五，而其功皆在上。井至上而后为元吉，鼎至上而后为大吉，皆所以全养人之利者也。</p></li><li><p>胡氏炳文曰 ：上九一阳横亘乎鼎耳之上，有铉象。金刚物自六五之柔而视上九之刚，则以为金铉；玉具刚柔之体，上九以刚居柔而又下得六五之柔，则以为玉铉。</p></li><li><p>熊氏良辅曰 ：井、鼎皆以上爻为吉。盖水以汲而出井为用，食以烹而出鼎为用也。</p></li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>此卦与大有只争初六一爻耳，馀爻皆同也。大有之彖辞直曰“元亨”，他卦所无也，惟鼎亦曰“元亨”。大有上爻曰“吉，无不利”，他爻所无也，惟鼎上爻亦曰“大吉，无不利”。以其皆为尚贤之卦故也。上九刚德为贤，六五尊而尚之，是尚贤也。在他卦有此象者，如贲、大畜、颐之类，其义皆善。其彖传亦多发尚贤养贤之义。然以卦义言之，则大有与鼎独为盛也。卦义之盛重于此两爻之相得，故吉无不利皆于上爻见之，即彖所谓“元亨”者也。又易中大象言天命者，亦惟此两卦，一曰“顺天休命”，一曰“正位凝命”。《书》曰：“天命有德，五服五章哉！”故退不肖而进贤者，天之命也。大有以遏恶扬善为顺天，此则推本于正位以凝命，所谓“君正莫不正”者，用能协于上下以承天休也。</p><p>象曰：玉铉在上，刚柔节也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>刚而温，乃有节也。上居成功致用之地，而刚柔中节，所以大吉无不利也。井、鼎皆以上出为成功，而鼎不云“元吉”，何也？曰：井之功用皆在上出，又有博施有常之德，是以元吉。鼎以烹饪为功，居上为成德，与井异，以刚柔节，故得大吉也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li>熊氏良辅曰 ：上以刚居柔，故曰“刚柔节”，而比德于玉也。</li></ul><p>总论</p><p>丘氏富国曰：初为足，故曰“颠趾”；二、三、四为腹，故曰“有实”、“曰雉膏”、“曰公𫗧”；五为耳，故曰“黄耳”；上为铉，故曰“玉铉”。此岂非全鼎之象乎？然初曰“趾”，四亦曰“足”者，以四应乎初，而四之足即初也。上曰“铉”，而五亦曰“铉”者，以五附乎上，五之铉即上也。五曰“耳”，而三亦曰“耳”者，则以三无应乎五，而有“鼎耳革”之象。</p>',126)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
